const fs = require('fs');

function main() {
  const data = fs.readFileSync(0, 'utf8');
  const len = data.length;
  let ptr = 0;

  function readInt() {
    while (ptr < len) {
      const c = data.charCodeAt(ptr);
      if (c >= 48 && c <= 57) break;
      ptr++;
    }
    let x = 0;
    while (ptr < len) {
      const c = data.charCodeAt(ptr);
      if (c < 48 || c > 57) break;
      x = x * 10 + (c - 48);
      ptr++;
    }
    return x;
  }

  const n = readInt();
  const k = readInt();
  const m = n - 1;

  const deg = new Int32Array(n + 2);
  const ea = new Int32Array(m), eb = new Int32Array(m);
  for (let i = 0; i < m; i++) {
    const a = readInt(), b = readInt();
    ea[i] = a; eb[i] = b;
    deg[a]++; deg[b]++;
  }
  const start = new Int32Array(n + 2);
  for (let i = 1; i <= n; i++) start[i + 1] = start[i] + deg[i];
  const adj = new Int32Array(2 * m);
  const pos = new Int32Array(n + 2);
  for (let i = 1; i <= n; i++) pos[i] = start[i];
  for (let i = 0; i < m; i++) {
    adj[pos[ea[i]]++] = eb[i];
    adj[pos[eb[i]]++] = ea[i];
  }

  // BFS a partir da sala 1 (ordem: pais antes dos filhos)
  const order = new Int32Array(n);
  const parent = new Int32Array(n + 1);
  const seen = new Uint8Array(n + 1);
  let qt = 0;
  order[qt++] = 1; seen[1] = 1;
  for (let qh = 0; qh < qt; qh++) {
    const v = order[qh];
    for (let j = start[v], e = start[v + 1]; j < e; j++) {
      const c = adj[j];
      if (!seen[c]) { seen[c] = 1; parent[c] = v; order[qt++] = c; }
    }
  }

  const uncArr = new Int32Array(n + 1); // maior distância (na subárvore) a um vértice ainda não coberto (-1 = nenhum)
  const covArr = new Int32Array(n + 1); // menor distância a um radar na subárvore (limitado a R+1)

  // Verifica se é possível cobrir toda a árvore com k radares de raio R (guloso bottom-up, ótimo)
  function check(R) {
    const cap = R + 1;
    let cnt = 0;
    for (let i = n - 1; i >= 0; i--) {
      const v = order[i];
      const p = parent[v];
      let unc = -1, cov = cap;
      for (let j = start[v], e = start[v + 1]; j < e; j++) {
        const c = adj[j];
        if (c === p) continue;
        const u = uncArr[c] + 1;
        if (u > unc) unc = u;
        let cc = covArr[c] + 1;
        if (cc > cap) cc = cap;
        if (cc < cov) cov = cc;
      }
      if (cov > R) {
        // o próprio vértice v não está coberto por radar abaixo
        if (unc < 0) unc = 0;
      } else if (unc >= 0 && unc + cov <= R) {
        // todos os descobertos da subárvore ficam cobertos pelo radar mais próximo
        unc = -1;
      }
      if (unc === R) {
        // forçado: vértice a distância R precisa de radar agora; colocar em v é ótimo
        cnt++;
        uncArr[v] = -1;
        covArr[v] = 0;
      } else {
        uncArr[v] = unc;
        covArr[v] = cov;
      }
    }
    if (uncArr[1] >= 0) cnt++; // sobrou vértice descoberto: radar na raiz
    return cnt <= k;
  }

  // Busca binária no menor R viável
  let lo = 0, hi = n;
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (check(mid)) hi = mid; else lo = mid + 1;
  }
  process.stdout.write(lo + '\n');
}

main();
